import re, sys
def esc(s):
    s = s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    s = s.replace("'", "\\'").replace('"', '\\"')
    return s
def write(path, idx):
    out = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
    for k, v in S.items():
        attrs = ' translatable="false"' if k == "app_name" and idx == 0 else ''
        if k == "app_name" and idx == 1: continue
        out.append(f'    <string name="{k}"{attrs}>{esc(v[idx])}</string>')
    for k, v in P.items():
        out.append(f'    <plurals name="{k}">')
        for q, t in v[idx].items(): out.append(f'        <item quantity="{q}">{esc(t)}</item>')
        out.append('    </plurals>')
    out.append('</resources>')
    open(path, 'w').write("\n".join(out) + "\n")

used = set(re.findall(r"R\.(?:string|plurals)\.([a-z0-9_]+)", sys.stdin.read()))
missing = used - set(S) - set(P); unused = set(S) - used - {"app_name"}
for k,(en,de) in S.items():
    if sorted(re.findall(r"%\d\$[sd]", en)) != sorted(re.findall(r"%\d\$[sd]", de)): print("PLACEHOLDER MISMATCH", k)
print("missing:", missing, "unused:", unused)
import os
base = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "app", "src", "main", "res") + "/"
write(base + "values/strings.xml", 0); write(base + "values-de/strings.xml", 1)
